def _website_upload(file_storage, folder, allowed={'.jpg','.jpeg','.png','.webp','.svg'}):
    if not file_storage or not file_storage.filename:
        return None
    ext=os.path.splitext(secure_filename(file_storage.filename))[1].lower()
    if ext not in allowed:
        raise ValueError("Only JPG, PNG, WEBP or SVG images are allowed.")
    target=os.path.join(current_app.static_folder,'uploads',folder); os.makedirs(target,exist_ok=True)
    filename=f"{uuid.uuid4().hex}{ext}"
    file_storage.save(os.path.join(target,filename))
    return f"uploads/{folder}/{filename}"

@admin_bp.route('/website/hero')
def website_hero():
    slides=WebsiteHeroSlide.query.order_by(WebsiteHeroSlide.sort_order.asc(), WebsiteHeroSlide.id.asc()).all()
    return render_template('admin/website_hero.html', slides=slides)

@admin_bp.route('/website/hero/new', methods=['GET','POST'])
def website_hero_new():
    if request.method=='POST':
        title=request.form.get('title','').strip(); image=request.files.get('image')
        if not title or not image or not image.filename:
            flash('Hero title and image are required.','danger'); return render_template('admin/website_hero_form.html', slide=None)
        try: image_path=_website_upload(image,'hero')
        except ValueError as e:
            flash(str(e),'danger'); return render_template('admin/website_hero_form.html', slide=None)
        slide=WebsiteHeroSlide(kicker=request.form.get('kicker','').strip(),title=title,text=request.form.get('text','').strip(),image_path=image_path,button_text=request.form.get('button_text','').strip() or 'Explore School',button_url=request.form.get('button_url','').strip() or '#about',sort_order=int(request.form.get('sort_order') or 0),is_active=request.form.get('is_active')=='1')
        db.session.add(slide); db.session.commit(); flash('Hero slide added.','success'); return redirect(url_for('admin.website_hero'))
    return render_template('admin/website_hero_form.html', slide=None)

@admin_bp.route('/website/hero/<int:slide_id>/edit', methods=['GET','POST'])
def website_hero_edit(slide_id):
    slide=WebsiteHeroSlide.query.get_or_404(slide_id)
    if request.method=='POST':
        slide.kicker=request.form.get('kicker','').strip(); slide.title=request.form.get('title','').strip() or slide.title; slide.text=request.form.get('text','').strip(); slide.button_text=request.form.get('button_text','').strip() or 'Explore School'; slide.button_url=request.form.get('button_url','').strip() or '#about'; slide.sort_order=int(request.form.get('sort_order') or 0); slide.is_active=request.form.get('is_active')=='1'
        image=request.files.get('image')
        if image and image.filename:
            try: slide.image_path=_website_upload(image,'hero')
            except ValueError as e: flash(str(e),'danger'); return render_template('admin/website_hero_form.html', slide=slide)
        db.session.commit(); flash('Hero slide updated.','success'); return redirect(url_for('admin.website_hero'))
    return render_template('admin/website_hero_form.html', slide=slide)

@admin_bp.route('/website/hero/<int:slide_id>/toggle', methods=['POST'])
def website_hero_toggle(slide_id):
    slide=WebsiteHeroSlide.query.get_or_404(slide_id); slide.is_active=not slide.is_active; db.session.commit(); flash('Hero slide status updated.','success'); return redirect(url_for('admin.website_hero'))

@admin_bp.route('/website/hero/<int:slide_id>/delete', methods=['POST'])
def website_hero_delete(slide_id):
    slide=WebsiteHeroSlide.query.get_or_404(slide_id); db.session.delete(slide); db.session.commit(); flash('Hero slide deleted.','success'); return redirect(url_for('admin.website_hero'))

