@admin_bp.route('/website/academics/<int:page_id>/edit', methods=['GET','POST'])
def website_academic_edit(page_id):
    page=WebsiteAcademicPage.query.get_or_404(page_id)
    if request.method=='POST':
        fields=['title','hero_kicker','intro','overview','highlights','curriculum','student_experience','support_programs','subjects','answer_summary','faq_json','seo_title','meta_description','seo_keywords','canonical_url']
        for field in fields: setattr(page,field,request.form.get(field,'').strip())
        page.is_published=request.form.get('is_published')=='1'
        image=request.files.get('hero_image')
        if image and image.filename:
            try: page.hero_image=_website_upload(image,'academics')
            except ValueError as e: flash(str(e),'danger'); return render_template('admin/website_academic_form.html', page=page)
        try:
            import json; json.loads(page.faq_json or '[]')
        except Exception:
            flash('FAQ JSON is invalid. Use a JSON array of question/answer objects.','danger'); return render_template('admin/website_academic_form.html', page=page)
        db.session.commit(); flash(f'{page.title} updated successfully.','success'); return redirect(url_for('admin.website_academics'))
    return render_template('admin/website_academic_form.html', page=page)

