(p/'app/templates/website/academic_page.html').write_text('''{% extends "base.html" %}{% block title %}{{page.seo_title or page.title}}{% endblock %}{% block extra_head %}<meta name="description" content="{{page.meta_description or page.answer_summary}}">{% if page.seo_keywords %}<meta name="keywords" content="{{page.seo_keywords}}">{% endif %}{% if page.canonical_url %}<link rel="canonical" href="{{page.canonical_url}}">{% endif %}<meta property="og:title" content="{{page.seo_title or page.title}}"><meta property="og:description" content="{{page.meta_description or page.answer_summary}}">{% if page.hero_image %}<meta property="og:image" content="{{url_for('static',filename=page.hero_image,_external=True)}}">{% endif %}{% endblock %}{% block public %}<div class="psg-site academic-public-page"><header class="psg-public-header"><nav class="psg-nav psg-sticky-nav is-scrolled"><div class="psg-container psg-nav-inner"><a class="psg-logo" href="{{url_for('main.index')}}"><img src="{{url_for('static',filename='site/images/school-logo.png')}}"><span><strong>PUBLIC SCHOOL GADAP</strong><small>KARACHI · LEARNING LEADERS</small></span></a><div class="psg-menu"><div class="psg-academic-dropdown"><a class="academic-menu-link" href="{{url_for('main.academic_page',slug=page.slug)}}">Academics <i class="bi bi-chevron-down"></i></a><div class="psg-academic-mega">{% for ap in WebsiteAcademicPage.query.filter_by(is_published=True).order_by(WebsiteAcademicPage.id.asc()).all() %}<a href="{{url_for('main.academic_page',slug=ap.slug)}}"><span class="mega-img" style="background-image:url('{{url_for('static',filename=ap.hero_image or 'site/images/elementary.png')}}')"></span><span><b>{{ap.title}}</b><small>{{ap.intro[:70]}}…</small></span></a>{% endfor %}</div></div><a href="{{url_for('main.index')}}#about">About</a><a href="{{url_for('main.index')}}#student-life">Student Life</a><a href="{{url_for('main.index')}}#admissions">Admissions</a><a href="{{url_for('main.index')}}#contact">Contact</a><a class="psg-login-link" href="{{url_for('auth.login')}}">Login</a></div></div></nav></header><section class="academic-hero" style="background-image:url('{{url_for('static',filename=page.hero_image or 'site/images/elementary.png')}}')"><div class="academic-hero-overlay"></div><div class="psg-container academic-hero-inner"><span class="psg-kicker">{{page.hero_kicker}}</span><h1>{{page.title}}</h1><p>{{page.intro}}</p></div></section><main class="academic-content"><div class="psg-container"><section class="academic-answer"><span class="psg-section-kicker">QUICK ANSWER</span><h2>{{page.title}} at Public School Gadap</h2><p>{{page.answer_summary}}</p></section><section class="academic-two-col"><div><span class="psg-section-kicker">OVERVIEW</span><h2>Learning with Purpose</h2><p>{{page.overview}}</p><div class="academic-block"><h3>Curriculum</h3><p>{{page.curriculum}}</p></div><div class="academic-block"><h3>Student Experience</h3><p>{{page.student_experience}}</p></div><div class="academic-block"><h3>Academic Support</h3><p>{{page.support_programs}}</p></div></div><aside><div class="academic-panel"><h3>Key Highlights</h3><div class="academic-pills">{% for x in page.highlights.replace('|','\n').splitlines() if x.strip() %}<span>{{x.strip()}}</span>{% endfor %}</div></div><div class="academic-panel"><h3>Subjects</h3><div class="subject-grid">{% for x in page.subjects.replace('|','\n').splitlines() if x.strip() %}<span>{{x.strip()}}</span>{% endfor %}</div></div></aside></section><section class="academic-faq"><span class="psg-section-kicker">FREQUENTLY ASKED QUESTIONS</span><h2>Questions & Answers</h2>{% for faq in faqs %}<details><summary>{{faq.question}}</summary><p>{{faq.answer}}</p></details>{% endfor %}</section></div></main><footer class="psg-footer psg-footer-premium"><div class="psg-container psg-footer-bottom"><span>© 2026 Public School Gadap. All rights reserved.</span><a href="{{url_for('main.index')}}">Back to Website</a></div></footer></div><script type="application/ld+json">{{ {'@context':'https://schema.org','@type':'EducationalOrganization','name':'Public School Gadap','url':request.url_root.rstrip('/'),'description':page.meta_description or page.answer_summary,'department':{'@type':'EducationalOrganization','name':page.title}}|tojson }}</script>{% endblock %}''')

