f=p/'app/templates/landing.html'; s=f.read_text()
# replace nav menu only first occurrence
old='<div class="psg-menu" id="publicMenu"><a href="#home">Home</a><a href="#about">About</a><a href="#academics">Academics</a><a href="#student-life">Student Life</a><a href="#admissions">Admissions</a><a href="#contact">Contact</a><a class="psg-login-link" href="{{ url_for(\'auth.login\') }}"><i class="bi bi-box-arrow-in-right"></i> Login</a></div>'
new='''<div class="psg-menu" id="publicMenu"><a href="#home">Home</a><a href="#about">About</a><div class="psg-academic-dropdown"><a class="academic-menu-link" href="#academics">Academics <i class="bi bi-chevron-down"></i></a><div class="psg-academic-mega">{% for ap in academic_pages %}<a href="{{url_for('main.academic_page',slug=ap.slug)}}"><span class="mega-img" style="background-image:url('{{url_for('static',filename=ap.hero_image or 'site/images/elementary.png')}}')"></span><span><b>{{ap.title}}</b><small>{{ap.intro[:72]}}…</small></span></a>{% endfor %}</div></div><a href="#student-life">Student Life</a><a href="#admissions">Admissions</a><a href="#contact">Contact</a><a class="psg-login-link" href="{{ url_for('auth.login') }}"><i class="bi bi-box-arrow-in-right"></i> Login</a></div>'''
