s += '''\n/* Phase 44 Website CMS + Academic mega menu */\n.psg-academic-dropdown{position:relative}.psg-academic-dropdown>a{display:flex;align-items:center;gap:.35rem}.psg-academic-mega{position:absolute;top:calc(100% + 16px);left:50%;transform:translateX(-50%) translateY(8px);width:min(760px,92vw);padding:16px;background:rgba(8,24,50,.96);backdrop-filter:blur(18px);border:1px solid rgba(255,255,255,.14);border-radius:20px;display:grid;grid-template-columns:repeat(3,1fr);gap:12px;opacity:0;visibility:hidden;pointer-events:none;transition:.35s ease;box-shadow:0 22px 60px rgba(0,0,0,.35);z-index:50}.psg-academic-dropdown:hover .psg-academic-mega,.psg-academic-dropdown:focus-within .psg-academic-mega{opacity:1;visibility:visible;pointer-events:auto;transform:translateX(-50%) translateY(0)}.psg-academic-mega>a{display:block;color:#fff;text-decoration:none;border-radius:15px;overflow:hidden;background:rgba(255,255,255,.07);transition:.35s ease}.psg-academic-mega>a:hover{transform:translateY(-7px) scale(1.02);background:rgba(255,255,255,.13)}.mega-img{display:block;height:115px;background-size:cover;background-position:center;transition:.45s ease}.psg-academic-mega>a:hover .mega-img{transform:scale(1.08)}.psg-academic-mega>a>span:last-child{display:block;padding:12px}.psg-academic-mega b{display:block;font-size:1.05rem;letter-spacing:.02em}.psg-academic-mega small{display:block;color:rgba(255,255,255,.72);margin-top:4px;line-height:1.35}.cms-hero-thumb{width:100%;height:220px;object-fit:cover}.academic-admin-image{height:180px;background-size:cover;background-position:center}.academic-admin-card{overflow:hidden;transition:.3s ease}.academic-admin-card:hover{transform:translateY(-6px);box-shadow:0 18px 45px rgba(12,36,68,.16)!important}.academic-hero{min-height:520px;background-size:cover;background-position:center;position:relative;display:flex;align-items:center}.academic-hero-overlay{position:absolute;inset:0;background:linear-gradient(90deg,rgba(3,19,43,.86),rgba(3,19,43,.38),rgba(3,19,43,.18))}.academic-hero-inner{position:relative;color:#fff;padding-top:90px;padding-bottom:90px}.academic-hero h1{font-size:clamp(3rem,7vw,6.4rem);font-weight:900;line-height:.95;letter-spacing:-.05em;margin:16px 0}.academic-hero p{max-width:760px;font-size:1.2rem;line-height:1.75;color:rgba(255,255,255,.88)}.academic-content{background:#f7f9fc;padding:70px 0}.academic-answer{background:linear-gradient(135deg,#0a2448,#123b70);color:#fff;padding:42px;border-radius:28px;margin-bottom:55px;box-shadow:0 25px 60px rgba(10,36,72,.18)}.academic-answer h2{font-size:2.2rem;font-weight:800}.academic-answer p{font-size:1.12rem;line-height:1.8;color:rgba(255,255,255,.88);max-width:980px}.academic-two-col{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(280px,.8fr);gap:40px}.academic-two-col h2{font-size:2.6rem;font-weight:850}.academic-two-col p{font-size:1.05rem;line-height:1.85;color:#516175}.academic-block{padding:22px 0;border-bottom:1px solid #e2e8f0}.academic-block h3{font-size:1.3rem;font-weight:800}.academic-panel{background:#fff;border-radius:22px;padding:24px;margin-bottom:20px;box-shadow:0 12px 40px rgba(12,36,68,.08)}.academic-panel h3{font-weight:800}.academic-pills{display:flex;flex-wrap:wrap;gap:9px}.academic-pills span,.subject-grid span{background:#eef5ff;border-radius:999px;padding:9px 12px;font-weight:650;color:#164273;font-size:.9rem;transition:.25s}.academic-pills span:hover,.subject-grid span:hover{transform:scale(1.06);background:#dbeaff}.subject-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.subject-grid span{border-radius:10px}.academic-faq{margin-top:65px}.academic-faq h2{font-size:2.4rem;font-weight:850;margin-bottom:22px}.academic-faq details{background:#fff;border-radius:15px;margin:10px 0;padding:18px 22px;box-shadow:0 7px 25px rgba(12,36,68,.06)}.academic-faq summary{cursor:pointer;font-weight:800;font-size:1.05rem}.academic-faq details p{color:#58697d;line-height:1.75;margin:14px 0 0}.academic-menu-link{white-space:nowrap}@media(max-width:900px){.psg-academic-mega{grid-template-columns:1fr;width:calc(100vw - 32px);max-height:70vh;overflow:auto}.psg-academic-dropdown:hover .psg-academic-mega{position:relative;left:0;top:0;transform:none}.academic-two-col{grid-template-columns:1fr}.academic-hero{min-height:430px}.academic-hero h1{font-size:3.4rem}}\n'''
